contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);
        require(amount > 0);
        uint256 beforeDistributed = c.totalDistributed();
        uint256 beforeRemaining = c.totalRemaining();
        uint256 beforeSupply = c.totalSupply();
        uint256 beforeValue = c.value();
        require(beforeRemaining >= beforeValue);
        uint256 expected = beforeValue;
        if (beforeValue > beforeRemaining) {
            expected = beforeRemaining;
        }
        uint256 beforeBalance = c.balanceOf(address(this));
        bool reverted;
        try c.getTokens{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(!reverted);
        assert(c.balanceOf(address(this)) == beforeBalance + expected);
        assert(c.totalDistributed() == beforeDistributed + expected);
        assert(c.totalRemaining() == beforeRemaining - expected);
        assert(c.totalSupply() == beforeSupply);
    }

    receive() external payable {}
}

