contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address spender, address from, address to, uint256 amount) public payable {
        require(to != address(0));
        require(from != address(0));
        require(amount > 0);
        uint256 allowanceBefore = c.allowance(from, spender);
        bool reverted;
        bool success;
        if (allowanceBefore < amount) {
            try c.transferFrom(from, to, amount) returns (bool s) {
                success = s;
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(reverted || !success);
        } else {
            uint256 fromBefore = c.balanceOf(from);
            uint256 toBefore = c.balanceOf(to);
            try c.transferFrom(from, to, amount) returns (bool s) {
                success = s;
                reverted = false;
            } catch {
                reverted = true;
            }
            if (!reverted && success) {
                assert(c.allowance(from, spender) == allowanceBefore - amount);
                assert(c.balanceOf(from) == fromBefore - amount);
                assert(c.balanceOf(to) == toBefore + amount);
            } else {
                assert(reverted || !success);
            }
        }
    }
}

